import{_ as l,o as t,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crash Telemetry - Observability in Action","description":"","frontmatter":{"title":"Ceph Crash Telemetry - Observability in Action","date":"2022-11-09T00:00:00.000Z","updated":"2022-11-10T00:00:00.000Z","tags":["Ceph","Telemetry","Crash Reporting","Observability","Data Analysis"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Crash_Telemetry_-_Observability_in_Action.md","filePath":"posts/2022/Ceph_Crash_Telemetry_-_Observability_in_Action.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_Crash_Telemetry_-_Observability_in_Action.md"};function o(s,e,n,h,m,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-telemetry项目更新-重点讨论crash-telemetry" tabindex="-1">会议主题：Telemetry项目更新，重点讨论Crash Telemetry <a class="header-anchor" href="#会议主题-telemetry项目更新-重点讨论crash-telemetry" aria-label="Permalink to &quot;会议主题：Telemetry项目更新，重点讨论Crash Telemetry&quot;">​</a></h4><h4 id="会议时间-会议日期" tabindex="-1">会议时间：[会议日期] <a class="header-anchor" href="#会议时间-会议日期" aria-label="Permalink to &quot;会议时间：[会议日期]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Telemetry项目概述</strong></p><ul><li>Telemetry服务允许集群收集匿名和非识别数据，用于分析和改进Ceph。</li><li>数据在公共仪表板上展示，用户可通过CLI或管理仪表板加入Telemetry服务。</li></ul></li><li><p><strong>Crash Telemetry通道</strong></p><ul><li>提供崩溃信息，包括崩溃回溯和Ceph代码中的位置。</li><li>默认开启，帮助开发者快速定位和修复问题。</li></ul></li><li><p><strong>隐私和数据安全</strong></p><ul><li>用户需同意CDLA共享许可才能加入Telemetry。</li><li>报告不包含敏感数据，如池名、主机名、对象名或内容。</li></ul></li><li><p><strong>Telemetry动机和好处</strong></p><ul><li>开发者：了解功能使用情况、升级节奏、版本采用率和设备健康状况。</li><li>用户：验证安装、预防设备故障、减少停机时间、自动化处理崩溃报告。</li></ul></li><li><p><strong>Telemetry架构和流程</strong></p><ul><li>崩溃时，守护进程生成崩溃转储，crash daemon定期检查并发送报告。</li><li>用户加入Telemetry后，Telemetry每天查询数据库并发送报告。</li></ul></li><li><p><strong>后端处理和分析</strong></p><ul><li>使用crash processor处理崩溃报告，去除偏移和地址，计算签名。</li><li>Redmine bot查询数据库，将崩溃签名映射到Redmine问题。</li></ul></li><li><p><strong>用户交互和反馈</strong></p><ul><li>用户可通过Redmine跟踪崩溃报告。</li><li>提供工具帮助用户跟踪和管理集群崩溃。</li></ul></li><li><p><strong>仪表板演示和成功案例</strong></p><ul><li>内部仪表板允许搜索整个数据库，查看崩溃趋势和受影响集群信息。</li><li>成功案例包括Telemetry bot自动发现并报告问题，开发团队据此修复并回溯到旧版本。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>优化Telemetry报告和后端处理流程。</li><li>开发更多用户友好的工具。</li><li>鼓励用户加入Telemetry服务。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><p>感谢所有参与者的积极参与和贡献，Telemetry项目取得显著成效，期待未来更多合作和改进。</p>',10)])])}const c=l(r,[["render",o]]);export{d as __pageData,c as default};
